command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: HYPNOTISCHES STARREN (Zerzal)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (!globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }
    if (!globalThis.DSK) return ui.notifications.error("Das DSK-Framework fehlt!");
    const DSK_FW = globalThis.DSK; 

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. WIRKENDEN PRÜFEN & QS HOLEN ---
    let casterToken = canvas.tokens.controlled[0];
    const casterActor = casterToken?.actor || game.user.character;
    if (!casterActor) return ui.notifications.warn("Bitte wähle zuerst deinen Token aus!");

    if (!casterToken) casterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor.id);

    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) await casterActor.unsetFlag("world", "letzteGabenQS"); 

    const gabenName = "Hypnotisches Starren";
    const ahne = "Zerzal";
    const finalEffektName = `${gabenName} (${ahne})`; // 🌙 Identischer Name für beide!
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const reichweite = 8;
    const iconBild = DSK_FW.Symbol(ahne); 

    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    // --- 3. ZIEL PRÜFEN ---
    let targetToken = game.user.targets.first();
    if (!targetToken) return ui.notifications.warn("Bitte markiere (Target) zuerst das Token deines Ziels!");

    let targetActor = targetToken.actor;
    if (!targetActor) return ui.notifications.warn("Das gewählte Ziel hat keinen gültigen Charakterbogen!");

    if (casterToken && targetToken && DSK_FW.Distanz) {
        const dist = DSK_FW.Distanz(casterToken, targetToken);
        if (dist > reichweite) return ui.notifications.warn(`Ziel verfehlt! ${targetToken.name} ist zu weit entfernt!`);
    }

    // --- 4. LEBEWESEN-PRÜFUNG ---
    const actorType = (targetActor.type || "").toLowerCase();
    const species = (targetActor.system?.species?.value || targetActor.system?.details?.species || "").toLowerCase();
    const excludedWords = ["untot", "geist", "vampir", "leiche", "golem", "skelett", "zombie", "dämon", "homunkulus", "mumie"];

    if (excludedWords.some(w => species.includes(w)) || actorType === "spirit") {
        return ChatMessage.create({
            speaker: { alias: "System" }, whisper: whisperTargets,
            content: `
                <div style="font-family: 'Signika', sans-serif;">
                    ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                    <div class="dskbox2" style="margin-top:10px; text-align:center;">
                        <p style="color:#b30000; font-weight:bold; font-size:1.1em;">Wirkung verpufft!</p>
                        <p><b>${targetActor.name}</b> ist kein Lebewesen.</p>
                    </div>
                </div>
            `
        });
    }

    // --- 5. EFFEKTE AUF BEIDE ANWENDEN ---
    for (let ef of casterActor.effects) { if ((ef.name || ef.label) === finalEffektName) await ef.delete(); }
    for (let ef of targetActor.effects) { if ((ef.name || ef.label) === finalEffektName) await ef.delete(); }

    // 🚩 HIER IST DIE ENDEKARTE:
    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("hypnotischesStarren", finalEffektName, "Der unheilvolle Blickkontakt bricht ab. Die Hypnose endet und die Erstarrung löst sich.");
    }

    // Effekt auf Caster (Aufpasser)
    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName, icon: iconBild, img: iconBild,
        description: `Du starrst <b>${targetActor.name}</b> in die Augen. Bewegst du dich, bricht die Hypnose!`,
        flags: { dsk: { isHypnoseCaster: true, targetUuid: targetActor.uuid } } 
    }]);

    // Effekt auf Ziel (Blocker)
    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName, icon: iconBild, img: iconBild,
        description: `Hypnotisiert von ${casterName}. Jede Bewegung ist unmöglich, bis der Blickkontakt bricht!`,
        changes: [{ key: "system.status.paralyzed", mode: 2, value: 1 }], 
        flags: { dsk: { isHypnotisiert: true, casterUuid: casterActor.uuid } } 
    }]);

    // --- 6. CHAT-KARTE ---
    await ChatMessage.create({
        speaker: { alias: "System" },
        content: `
            <div style="font-family: 'Signika', sans-serif;">
                ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                <div class="dskbox2" style="margin-top:10px; text-align:center;">
                    <p style="margin-bottom: 8px;"><b>${casterName}</b> starrt <b>${targetActor.name}</b> unheilvoll in die Augen!</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">
                        Das Ziel verliert sich völlig im Blick des Zerzalkindes und bleibt regungslos stehen.
                    </p>
                    <p style="margin-bottom: 8px; font-size:0.9em; color:#555;">
                        <i>(Das Ziel kann nicht mehr bewegt werden! Die Wirkung endet sofort, wenn das Ziel Schaden erleidet oder der Wirkende sich bewegt.)</i>
                    </p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px; font-weight:bold;">Wirkungsdauer:<br>${qsWert * 5} Kampfrunden</p>
                </div>
            </div>
        `
    });

    // --- 7. SOFORT-START DER WÄCHTER ---
    if (game.user.isGM && typeof LunasHypnoseWächterStart === "function") {
        LunasHypnoseWächterStart(); 
    } else if (!globalThis.LunasHypnoseWächterAktiv) {
        globalThis.LunasHypnoseWächterAktiv = true;

        // Blocker (Gegner)
        Hooks.on("preUpdateToken", (tokenDoc, change) => {
            if (change.x === undefined && change.y === undefined) return true;
            if (tokenDoc.actor && tokenDoc.actor.effects.some(e => (e.name || e.label) === finalEffektName && e.getFlag("dsk", "isHypnotisiert"))) {
                ui.notifications.warn(`Luna sagt 🌙: ${tokenDoc.name} ist hypnotisiert und völlig erstarrt!`);
                return false; 
            }
            return true;
        });

        // Bewegung (Caster)
        Hooks.on("updateToken", async (tokenDoc, change) => {
            if (!game.user?.isGM) return;
            if (change.x === undefined && change.y === undefined) return;
            if (tokenDoc.actor) {
                const cEff = tokenDoc.actor.effects.find(e => (e.name || e.label) === finalEffektName && e.getFlag("dsk", "isHypnoseCaster"));
                if (cEff) {
                    ui.notifications.info(`Hypnose gebrochen: ${tokenDoc.name} hat sich bewegt!`);
                    await cEff.delete(); 
                }
            }
        });

        // Schaden am Ziel
        Hooks.on("createChatMessage", async (msg) => {
            if (!game.user?.isGM) return;
            const rawContent = msg.content || "";
            const cleanText = rawContent.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
            if (!cleanText.includes("gewinnt gegen")) return;

            for (let t of canvas.tokens.placeables) {
                if (!t.actor) continue;
                const hypEff = t.actor.effects.find(e => (e.name || e.label) === finalEffektName && e.getFlag("dsk", "isHypnotisiert"));
                if (!hypEff) continue;

                const isTargetHit = rawContent.includes(t.actor.id) || cleanText.includes(t.actor.name) || (t.name && cleanText.includes(t.name));
                if (isTargetHit) {
                    ui.notifications.info(`Hypnose gebrochen: ${t.name} wurde angegriffen!`);
                    await hypEff.delete(); 
                }
            }
        });

        // Magische Kette (Das gegenseitige Löschen)
        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user?.isGM) return;
            // Ziel verliert Effekt -> Caster bereinigen
            if (effect.getFlag("dsk", "isHypnotisiert")) {
                const cUuid = effect.getFlag("dsk", "casterUuid");
                if (cUuid) {
                    const cDoc = await fromUuid(cUuid);
                    const cAct = cDoc?.documentName === "Token" ? cDoc.actor : cDoc;
                    if (cAct) {
                        const cEff = cAct.effects.find(e => e.getFlag("dsk", "isHypnoseCaster") && e.getFlag("dsk", "targetUuid") === effect.parent.uuid);
                        if (cEff) await cEff.delete();
                    }
                }
            }
            // Caster verliert Effekt -> Ziel bereinigen
            if (effect.getFlag("dsk", "isHypnoseCaster")) {
                const tUuid = effect.getFlag("dsk", "targetUuid");
                if (tUuid) {
                    const tDoc = await fromUuid(tUuid);
                    const tAct = tDoc?.documentName === "Token" ? tDoc.actor : tDoc;
                    if (tAct) {
                        const tEff = tAct.effects.find(e => e.getFlag("dsk", "isHypnotisiert") && e.getFlag("dsk", "casterUuid") === effect.parent.uuid);
                        if (tEff) await tEff.delete();
                    }
                }
            }
        });
    }
})();
